import type { DomainEvent, FamilyState, WeeklyResult } from '../domain/types.ts';

/**
 * Push notifications for domain events (spec 14: approvals, rewards, weekly summary).
 * `url` is the route the app opens on tap, so a parent approves with at most two
 * taps: the notification, then "Godkänn" (spec 15 acceptance criteria).
 *
 * Push messages pass through Expo, Apple and Google, outside the EU. They are
 * therefore neutral: no child names, challenge titles or rewards (spec 12). The
 * details are shown in the app after the tap.
 */

export type PushAudience = { kind: 'parents' } | { kind: 'child'; childId: string };

export interface PushMessage {
  audience: PushAudience;
  title: string;
  body: string;
  url: string;
}

const APP_NAME = 'JagKan!';

export function messagesForEvents(state: FamilyState, events: DomainEvent[]): PushMessage[] {
  const settings = state.family.settings.notifications;
  const out: PushMessage[] = [];
  for (const event of events) {
    if (event.type === 'completion_requested' && settings.approvals) {
      out.push({
        audience: { kind: 'parents' },
        title: APP_NAME,
        body: 'Ny förfrågan att godkänna 🎉',
        url: `/parent/approve/${event.challengeId}`,
      });
    } else if (event.type === 'reward_requested' && settings.approvals) {
      out.push({ audience: { kind: 'parents' }, title: APP_NAME, body: 'Ny önskan i belöningsbutiken 🎁', url: '/parent/rewards' });
    } else if (event.type === 'challenge_completed') {
      out.push({ audience: { kind: 'child', childId: event.childId }, title: APP_NAME, body: 'En vuxen har godkänt! ⭐', url: '/child' });
    } else if (event.type === 'reward_resolved' && event.confirmed) {
      out.push({ audience: { kind: 'child', childId: event.childId }, title: APP_NAME, body: 'En belöning är din! 🎁', url: '/child/shop' });
    }
  }
  return out;
}

/** Sunday-evening summary to the parents (spec 14.2 weekly-rollup). */
export function weeklySummaryMessage(state: FamilyState, result: WeeklyResult): PushMessage | null {
  if (!state.family.settings.notifications.weeklySummary || result.results.length === 0) return null;
  return { audience: { kind: 'parents' }, title: 'Veckan i JagKan!', body: 'Veckan är klar. Se hur det gick! 🌟', url: '/parent' };
}
